    public bool IsValid => Anchor != null && !string.IsNullOrEmpty(Verb);

    /// <summary>Display text, e.g. "[E]  Pick Up Wrench" or "[Q]  Grapple".</summary>
    public string Display =>
        string.IsNullOrEmpty(Label) ? $"[{Key}]  {Verb}" : $"[{Key}]  {Verb} {Label}";
