using UnityEngine;
using Flynn.Events;

/// <summary>
/// Robot energy system. Owns a 0–100 <see cref="IntVariable"/> battery and drains it
/// both passively (over time) and actively (from gameplay actions via <see cref="BatterySettings"/>).
/// The HUD reads the battery purely through <see cref="IntVariable.OnChanged"/>.
///
/// Supports a configurable <see cref="BatterySettings"/> SO for action costs and an
/// <c>infiniteBatteryDebug</c> toggle for sandbox testing without battery interference.
/// </summary>
[DefaultExecutionOrder(-40)]
public class RobotBattery : MonoBehaviour
{
    public const int Min = 0;
    public const int Max = 100;

    public static RobotBattery Instance { get; private set; }

    [Tooltip("The shared 0–100 battery value the HUD displays. Assign the same asset on PlayerHudPanel.")]
    [SerializeField] private IntVariable _battery;

    [Tooltip("Battery settings: action costs, passive drain, debug mode.")]
    [SerializeField] private BatterySettings _settings;

    [SerializeField, Range(Min, Max)] private int _startCharge = 100;

    [Tooltip("Passive drain in battery points per second. Overridden by BatterySettings if assigned.")]
    [SerializeField] private float _drainPerSecond = 1f;

    [SerializeField] private bool _autoDrain = true;

    private float _accum;

    // ── API ──────────────────────────────────────────────────────────────────

    public int Charge => _battery != null ? _battery.Value : 0;
    public bool IsEmpty => Charge <= Min;
    public bool IsFull  => Charge >= Max;

    /// <summary>Whether infinite battery debug mode is active.</summary>
    public bool InfiniteDebug => _settings != null && _settings.infiniteBatteryDebug;

    /// <summary>Access to battery settings for cost lookups (read-only).</summary>
    public BatterySettings Settings => _settings;

    /// <summary>
    /// Can the battery afford this cost? Returns true if infinite debug is on,
    /// or if there's enough charge (as a float, so partial charges are possible).
    /// </summary>
    public bool CanSpend(float cost)
    {
        if (_settings != null && _settings.infiniteBatteryDebug) return true;
        return Charge >= cost;
    }

    /// <summary>
    /// Spend a float amount of battery (for action costs). No-op in infinite debug mode.
    /// Publishes <see cref="BatteryChanged"/> and threshold events.
    /// </summary>
    public void Spend(float cost)
    {
        if (_settings != null && _settings.infiniteBatteryDebug) return;
        if (cost <= 0f) return;
        _accum -= cost;
        FlushAccum();
    }

    /// <summary>Drain over time (continuous actions like pulling/scanning).</summary>
    public void DrainOverTime(float costPerSecond)
    {
        if (_settings != null && _settings.infiniteBatteryDebug) return;
        _accum -= costPerSecond * Time.deltaTime;
        FlushAccum();
    }

    /// <summary>Add charge (negative to drain). Clamped to 0–100; notifies via the IntVariable.</summary>
    public void AddCharge(int amount) => SetCharge(Charge + amount);

    /// <summary>Drain charge by a positive amount.</summary>
    public void Drain(int amount) => SetCharge(Charge - Mathf.Abs(amount));

    public void SetCharge(int value)
    {
        if (_battery == null) return;
        int prev = Charge;
        _battery.Value = Mathf.Clamp(value, Min, Max);
        int current = Charge;

        if (GameEventBus.Instance != null)
        {
            GameEventBus.Instance.Publish(new BatteryChanged(current, Max));
            if (current <= Min && prev > Min)
                GameEventBus.Instance.Publish(new BatteryEmpty());
            else if (current <= LowThreshold && prev > LowThreshold)
                GameEventBus.Instance.Publish(new BatteryLow(current, (float)current / Max));
        }
    }

    public void SetAutoDrain(bool on) => _autoDrain = on;

    private int LowThreshold => _settings != null ? _settings.lowBatteryThreshold : 20;

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Debug.LogWarning($"[RobotBattery] Duplicate; destroying {name}.", this);
            Destroy(this);
            return;
        }
        Instance = this;
        SetCharge(_startCharge);
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    private void Update()
    {
        if (!_autoDrain || _battery == null || IsEmpty) return;

        float drainRate = _settings != null && _settings.enablePassiveDrain
            ? _settings.passiveDrainPerSecond
            : _drainPerSecond;

        if (drainRate <= 0f) return;

        _accum -= drainRate * Time.deltaTime;
        FlushAccum();
    }

    /// <summary>Flush accumulated fractional drain to the integer battery value.</summary>
    private void FlushAccum()
    {
        if (_accum >= 0f) return;
        int whole = Mathf.FloorToInt(-_accum);
        if (whole <= 0) return;
        _accum += whole;
        Drain(whole);
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Central UI relay — same factory/hub pattern as ResourceManager and PlayerInventory: gameplay
/// systems fire an inbound signal (<see cref="SignalShow"/> / <see cref="SignalHide"/> /
/// <see cref="SignalToggle"/>), the manager routes it to the matching reusable panel, then
/// broadcasts an outbound event (<see cref="OnPanelShown"/> / <see cref="OnPanelHidden"/>).
///
/// Callers never reference a concrete screen — they only know a <see cref="UIPanelId"/> and reach
/// the manager through <see cref="Instance"/>. The manager owns the list of reusable panels and
/// reuses them (show/hide), never instantiating per request.
///
/// One per scene. Runs early (negative execution order) so <see cref="Instance"/> and the registry
/// exist before any caller's Awake/OnEnable.
/// </summary>
[DefaultExecutionOrder(-100)]
public class UIManager : MonoBehaviour
{
    public static UIManager Instance { get; private set; }

    [Tooltip("Log each show/hide signal. Off for production.")]
    [SerializeField] private bool _debugLog = true;

    [Tooltip("Reusable panels managed here. Drop UIPanel components in, or Register at runtime.")]
    [SerializeField] private List<UIPanel> _panels = new();

    private readonly Dictionary<UIPanelId, IUIPanel> _registry = new();

    /// <summary>Raised after a panel is shown. Subscribe with += on startup.</summary>
    public event Action<UIPanelId> OnPanelShown;
    /// <summary>Raised after a panel is hidden. Subscribe with += on startup.</summary>
    public event Action<UIPanelId> OnPanelHidden;

    // ── Signals (inbound) ───────────────────────────────────────────────────────

    /// <summary>Signal: show the panel with this id. No-op (warns) if none is registered.</summary>
    public void SignalShow(UIPanelId id)
    {
        if (!TryGet(id, out IUIPanel panel)) return;
        if (_debugLog) Debug.Log($"[UIManager] show {id}");
        panel.Show();
        OnPanelShown?.Invoke(id);
    }

    /// <summary>Signal: hide the panel with this id.</summary>
    public void SignalHide(UIPanelId id)
    {
        if (!TryGet(id, out IUIPanel panel)) return;
        if (_debugLog) Debug.Log($"[UIManager] hide {id}");
        panel.Hide();
        OnPanelHidden?.Invoke(id);
    }

    /// <summary>Signal: toggle the panel's visibility.</summary>
    public void SignalToggle(UIPanelId id)
    {
        if (!TryGet(id, out IUIPanel panel)) return;
        if (panel.IsVisible) SignalHide(id);
        else SignalShow(id);
    }

    public bool IsVisible(UIPanelId id) => TryGet(id, out IUIPanel p, warn: false) && p.IsVisible;

    // ── Registration ──────────────────────────────────────────────────────────

    /// <summary>Register a panel at runtime (panels in the serialized list register automatically).</summary>
    public void Register(IUIPanel panel)
    {
        if (panel == null || panel.PanelId == UIPanelId.None) return;
        _registry[panel.PanelId] = panel;
    }

    public void Unregister(IUIPanel panel)
    {
        if (panel == null) return;
        if (_registry.TryGetValue(panel.PanelId, out IUIPanel existing) && existing == panel)
            _registry.Remove(panel.PanelId);
    }

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Debug.LogWarning($"[UIManager] Duplicate; destroying {name}.", this);
            Destroy(this);
            return;
        }
        Instance = this;

        foreach (UIPanel panel in _panels)
        {
            if (panel == null) continue;
            if (panel.PanelId == UIPanelId.None)
            {
                Debug.LogWarning($"[UIManager] '{panel.name}' has PanelId.None; skipped.", panel);
                continue;
            }
            Register(panel);
        }
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    // ── Private ───────────────────────────────────────────────────────────────

    private bool TryGet(UIPanelId id, out IUIPanel panel, bool warn = true)
    {
        if (_registry.TryGetValue(id, out panel) && panel != null) return true;
        if (warn) Debug.LogWarning($"[UIManager] No panel registered for {id}.", this);
        return false;
    }
}

using UnityEngine;
using UnityEngine.UIElements;

/// <summary>
/// Base for UI Toolkit panels driven by <see cref="UIManager"/>. Wraps the one fragile part of
/// UI Toolkit — element binding — in the proven defense: the visual tree may not exist during
/// OnEnable (component order isn't guaranteed), so <see cref="Bind"/> is retried from Update until
/// it succeeds. Subclasses query/cache elements in Bind and never touch the tree before it's ready.
///
/// Show/Hide toggle the root's <c>display</c> instead of the GameObject, so the UIDocument stays
/// alive and we never rebuild + rebind the tree on every show (which is what made the old HUD
/// flaky). The GameObject itself stays active.
/// </summary>
[RequireComponent(typeof(UIDocument))]
public abstract class UIToolkitPanel : UIPanel
{
    [Tooltip("Visible as soon as it binds (always-present HUD = true; pop-ups like the hover tag = false).")]
    [SerializeField] private bool _startVisible = true;

    protected UIDocument Document { get; private set; }
    protected VisualElement Root { get; private set; }

    private bool _bound;

    // ── Unity messages ────────────────────────────────────────────────────────

    protected virtual void Awake()
    {
        Document = GetComponent<UIDocument>();
        IsVisible = _startVisible;
    }

    protected virtual void OnEnable()
    {
        _bound = false;
        TryBind();
    }

    protected virtual void Update()
    {
        if (!_bound) TryBind();
    }

    // ── Show / hide (display toggle, document stays alive) ──────────────────────

    public override void Show()
    {
        IsVisible = true;
        ApplyDisplay();
        OnShow();
    }

    public override void Hide()
    {
        IsVisible = false;
        ApplyDisplay();
        OnHide();
    }

    // ── Binding ─────────────────────────────────────────────────────────────────

    /// <summary>Query and cache elements. Return false if the tree isn't built yet (retried next frame).</summary>
    protected abstract bool Bind(VisualElement root);

    /// <summary>Called once after a successful bind — do the first data refresh here.</summary>
    protected virtual void OnBound() { }

    private void TryBind()
    {
        if (Document == null) return;
        VisualElement root = Document.rootVisualElement;
        if (root == null) return;
        if (!Bind(root)) return; // sentinel element missing → tree not ready, try again next frame

        Root = root;
        _bound = true;
        ApplyDisplay();
        OnBound();
    }

    private void ApplyDisplay()
    {
        if (Root != null)
            Root.style.display = IsVisible ? DisplayStyle.Flex : DisplayStyle.None;
    }
}

using UnityEngine;
using Flynn.Events;

// 2.5D force-based character controller. Moves on the XZ plane via acceleration
// toward a target velocity, so Unity physics drives interactions: PhysicMaterial
// friction (ice/mud), Rigidbody.drag (water), and AddForce zones (wind) all
// compose naturally instead of being overwritten. Small jump impulse, gravity
// handled by the Rigidbody.
[RequireComponent(typeof(Rigidbody))]
public class SolarpunkCharacterController : MonoBehaviour
{
    [SerializeField] private float moveSpeed = 5f;        // target horizontal speed under input
    [SerializeField] private float acceleration = 40f;    // how hard we drive toward target
    [SerializeField] private float jumpForce = 6f;
    // Baseline drag is 0: accel-to-target already arrests horizontal motion when input is
    // released (target velocity 0 -> decel force), so we need no passive drag — and drag is
    // isotropic, which would damp jump/fall. Water zones raise this temporarily; ice keeps it low.
    [SerializeField] private float groundDrag = 0f;
    [SerializeField] private float groundCheckDistance = 0.12f;
    [SerializeField] private LayerMask groundLayers = ~0;
    // Ice low-grip is re-asserted by the zone every physics step. Latch it for a short grace
    // window so a single missed OnTriggerStay (e.g. player center crossing the trigger edge
    // while the capsule is still on the ice) doesn't snap the ground brake back on for a step
    // and bleed the slide. Grace ends well before the player is truly off the ice.
    [SerializeField] private float lowGripGrace = 0.2f;

    public Vector3 MoveInput => moveInput;
    public bool IsGrounded => isGrounded;
    /// <summary>Horizontal speed normalized 0-1 relative to moveSpeed.</summary>
    public float NormalizedSpeed => rb != null
        ? Mathf.Clamp01(new Vector2(rb.velocity.x, rb.velocity.z).magnitude / moveSpeed)
        : 0f;

    /// <summary>Multiplies steering force each physics step. Ice sets this low (slidey, weak
    /// steering, momentum dominates) — kept &gt;0 so the player can always escape ice. Auto-resets to 1.</summary>
    public float SteeringControl { get; set; } = 1f;

    /// <summary>Multiplies the target move speed each physics step. Water/Mud set this below 1 to
    /// slow the player noticeably (lowering the target, since drag/friction barely dents accel-to-target).
    /// Auto-resets to 1.</summary>
    public float SpeedMultiplier { get; set; } = 1f;

    /// <summary>Set false each physics step by a mud zone while grounded on it: blocks jumping
    /// ("mud stops vertical movement"). Auto-resets to true.</summary>
    public bool CanJump { get; set; } = true;

    /// <summary>Set true each physics step by an ice zone: the controller stops braking toward
    /// zero when there's no input, so momentum carries (glide). Steering still applies (scaled by
    /// SteeringControl) so the player can nudge off the ice. Auto-resets to false.</summary>
    public bool LowGrip { get; set; } = false;

    public Vector3 RbVelocityDirection { get; private set; }

    private Rigidbody rb;
    private Collider bodyCollider;
    private bool isGrounded;
    private bool wasGrounded;
    private Vector3 moveInput;
    private bool jumpQueued;
    private float lowGripTimer;

    private void Awake()
    {
        rb = GetComponent<Rigidbody>();
        bodyCollider = GetComponent<Collider>();
        rb.drag = groundDrag;
        rb.freezeRotation = true;
    }

    private void Update()
    {
        moveInput.x = Input.GetAxisRaw("Horizontal");
        moveInput.z = Input.GetAxisRaw("Vertical");
        RbVelocityDirection = rb.velocity.normalized;
        if (moveInput.sqrMagnitude > 1f) moveInput.Normalize();

        if (Input.GetButtonDown("Jump")) jumpQueued = true;
    }



    private void FixedUpdate()
    {
        UpdateGrounded();

        // Accelerate toward the input-driven target velocity (XZ only). External forces
        // (wind AddForce) and surface friction are left to the solver. SpeedMultiplier
        // lowers the target (water/mud slow); SteeringControl scales the force (ice = slidey,
        // weak steering so momentum carries, but never 0 so the player can't get stuck).
        Vector3 horizVel = new Vector3(rb.velocity.x, 0f, rb.velocity.z);
        Vector3 inputDir = new Vector3(moveInput.x, 0f, moveInput.z);
        bool idle = inputDir.sqrMagnitude < 0.01f;
        // Latch low-grip: refresh the timer while the zone asserts it, otherwise decay it.
        // The brake stays off for the whole grace window, surviving single-step trigger gaps.
        if (LowGrip) lowGripTimer = lowGripGrace;
        else lowGripTimer -= Time.fixedDeltaTime;
        bool lowGrip = lowGripTimer > 0f;
        if (lowGrip)
        {
            // Ice: momentum carries, input only steers. With input, push in the input direction
            // WITHOUT the "- horizVel" brake term (that term is what kills the slide on normal
            // ground), so existing momentum is preserved and the velocity vector rotates toward
            // the input instead of being reset to it. Speed is capped to moveSpeed so the additive
            // force can't run away. Idle = no force, the frictionless surface keeps the glide.
            if (!idle)
            {
                rb.AddForce(inputDir * moveSpeed * acceleration * SteeringControl, ForceMode.Acceleration);
                Vector3 hv = new Vector3(rb.velocity.x, 0f, rb.velocity.z);
                float maxSpeed = moveSpeed * SpeedMultiplier;
                if (hv.magnitude > maxSpeed)
                {
                    hv = hv.normalized * maxSpeed;
                    rb.velocity = new Vector3(hv.x, rb.velocity.y, hv.z);
                }
            }
        }
        else
        {
            // Normal ground: accelerate toward the input-driven target velocity (XZ only).
            // SpeedMultiplier lowers the target (water/mud slow); SteeringControl scales the
            // force (wind = weak self-correction so wind blows you).
            Vector3 targetVel = inputDir * moveSpeed * SpeedMultiplier;
            Vector3 dv = targetVel - horizVel;
            rb.AddForce(dv * acceleration * SteeringControl, ForceMode.Acceleration);
        }

        if (jumpQueued && isGrounded && CanJump)
        {
            Vector3 v = rb.velocity; v.y = 0f; rb.velocity = v;
            rb.AddForce(Vector3.up * jumpForce, ForceMode.Impulse);
            isGrounded = false;
            PublishEvent(new PlayerJumped(transform.position));
        }
        jumpQueued = false;

        // Per-step terrain modifiers; zones re-assert them in OnTriggerStay (which fires
        // after FixedUpdate within the same physics step).
        SteeringControl = 1f;
        SpeedMultiplier = 1f;
        CanJump = true;
        LowGrip = false;

        // Detect landing (was airborne, now grounded).
        if (!wasGrounded && isGrounded)
            PublishEvent(new PlayerLanded(transform.position));
        wasGrounded = isGrounded;
    }

    private void UpdateGrounded()
    {
        if (bodyCollider == null)
        {
            isGrounded = false;
            return;
        }

        Vector3 origin = bodyCollider.bounds.center;
        origin.y = bodyCollider.bounds.min.y + 0.02f;

        isGrounded = Physics.Raycast(
            origin,
            Vector3.down,
            groundCheckDistance,
            groundLayers,
            QueryTriggerInteraction.Ignore
        );
    }

    private static void PublishEvent<T>(T evt) where T : struct
    {
        if (GameEventBus.Instance != null) GameEventBus.Instance.Publish(evt);
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        // Ground check ray
        if (bodyCollider != null)
        {
            Vector3 origin = bodyCollider.bounds.center;
            origin.y = bodyCollider.bounds.min.y + 0.02f;
            Debug.DrawLine(origin, origin + Vector3.down * groundCheckDistance,
                isGrounded ? Color.green : Color.red);
        }

        // Velocity vector
        if (rb != null)
        {
            Debug.DrawRay(transform.position, rb.velocity, Color.cyan);
        }
    }
#endif
}

using System;
using UnityEngine;

/// <summary>
/// Single source of truth for the mouse pointer. One per scene (lives on the UI manager object).
/// Every frame it reads the cursor, builds ONE world ray, and casts ONCE against a combined layer
/// mask — then caches the result. Gameplay and UI read these cached values instead of each running
/// their own <c>Camera.ScreenPointToRay(Input.mousePosition)</c> + <c>Physics.Raycast</c>.
///
/// Same hub idea as the other managers: record the signal once, everyone else just reads it. Runs
/// early (negative execution order) so the cache is fresh before any default-order consumer's Update.
/// </summary>
[DefaultExecutionOrder(-90)]
public class MousePointer : MonoBehaviour
{
    public static MousePointer Instance { get; private set; }

    [Tooltip("Camera the cursor ray is built from. Falls back to Camera.main.")]
    [SerializeField] private Camera _camera;
    [Tooltip("Combined mask for the per-frame world cast — the union of everything UI/gameplay needs.")]
    [SerializeField] private LayerMask _worldMask = ~0;
    [SerializeField] private float _maxDistance = 100f;

    // ── Cached each frame ───────────────────────────────────────────────────────

    /// <summary>Cursor position in screen pixels (== Input.mousePosition).</summary>
    public Vector2 ScreenPosition { get; private set; }
    /// <summary>Ray from the camera through the cursor.</summary>
    public Ray WorldRay { get; private set; }
    /// <summary>True if this frame's cast hit a collider on <see cref="_worldMask"/>.</summary>
    public bool HasHit { get; private set; }
    /// <summary>This frame's raycast hit (valid only when <see cref="HasHit"/>).</summary>
    public RaycastHit Hit { get; private set; }
    /// <summary>Hit point if we hit, else the ray projected to max distance (always usable as an aim target).</summary>
    public Vector3 WorldPoint { get; private set; }
    /// <summary>Collider under the cursor this frame, or null.</summary>
    public Collider HoverCollider { get; private set; }
    /// <summary>GameObject under the cursor this frame, or null.</summary>
    public GameObject HoverObject { get; private set; }

    /// <summary>Fires when the hovered GameObject changes (including to/from null).</summary>
    public event Action<GameObject> OnHoverChanged;

    private GameObject _lastHover;

    // ── Public helpers ──────────────────────────────────────────────────────────

    /// <summary>True when the current hover object sits on one of the given layers.</summary>
    public bool HoverOnLayers(LayerMask mask)
        => HoverObject != null && (mask.value & (1 << HoverObject.layer)) != 0;

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Debug.LogWarning($"[MousePointer] Duplicate; destroying {name}.", this);
            Destroy(this);
            return;
        }
        Instance = this;
        if (_camera == null) _camera = Camera.main;
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    private void Update()
    {
        if (_camera == null)
        {
            _camera = Camera.main;
            if (_camera == null) return;
        }

        ScreenPosition = Input.mousePosition;
        WorldRay = _camera.ScreenPointToRay(ScreenPosition);

        HasHit = Physics.Raycast(WorldRay, out RaycastHit hit, _maxDistance, _worldMask, QueryTriggerInteraction.Ignore);
        Hit = hit;

        if (HasHit)
        {
            WorldPoint = hit.point;
            HoverCollider = hit.collider;
            HoverObject = hit.collider != null ? hit.collider.gameObject : null;
        }
        else
        {
            WorldPoint = WorldRay.GetPoint(_maxDistance);
            HoverCollider = null;
            HoverObject = null;
        }

        if (HoverObject != _lastHover)
        {
            _lastHover = HoverObject;
            OnHoverChanged?.Invoke(HoverObject);
        }
    }
}

